            float d_up    = abs(c - get_guide_px(x, y - 3));
            float d_down  = abs(c - get_guide_px(x, y + 3));
            float d_left  = abs(c - get_guide_px(x - 3, y));
            float d_right = abs(c - get_guide_px(x + 3, y));
