    ivec2 targetLogicalTile = targetTile + ivec2(uTargetGridMin);
    vec2 targetCenter = (vec2(targetLogicalTile) + vec2(0.5)) * float(uTargetTileStride);
    vec2 initialGrid = targetCenter / (uInitialScale * float(uInitialTileStride)) - vec2(float(uInitialGridMin) + 0.5);
    vec2 nearestPosition = roundEven(initialGrid);
    ivec2 nearest = ivec2(nearestPosition);
    ivec2 nextX = nearest + ivec2(initialGrid.x < nearestPosition.x ? -1 : 1, 0);
    ivec2 nextY = nearest + ivec2(0, initialGrid.y < nearestPosition.y ? -1 : 1);
