// sh060: highlight_clip_dilate (+0xd0): base clip mask
static const char* kFastHlClipDilate=R"FM(#version 310 es
precision highp float;
precision highp int;

in highp vec2 tex_coord;
layout(location = 0) out vec2 o_clip_mask; // R = dilated clip, G = near clip

uniform sampler2D u_base_bayer;
uniform vec4 u_tex_size; // xy = (W/2, H/2), zw = (1/(W/2), 1/(H/2))
uniform vec4 u_black_level;
uniform float u_white_level;

void main() {
    float norm = 1.0 / max(1.0, u_white_level - u_black_level.r);
    
    // Sample center quad to check near-clip
    vec4 center_quad = texture(u_base_bayer, tex_coord);
    vec4 center_norm = (center_quad - u_black_level) * norm;
    float center_max = max(max(center_norm.r, center_norm.g), max(center_norm.b, center_norm.a));
    float near_clip = smoothstep(0.70, 0.88, center_max);
    // P497: the near-clip gate over the 3 x 3 quads around: a thin light (a fan's LED ring, 1 - 2 quads) blurred under the gate's
    // threshold at its own centre point and kept the base's white there
    for (int dy = -1; dy <= 1; ++dy) for (int dx = -1; dx <= 1; ++dx) {
        vec4 qn = (texture(u_base_bayer, tex_coord + vec2(float(dx), float(dy)) * u_tex_size.zw) - u_black_level) * norm;
        near_clip = max(near_clip, smoothstep(0.70, 0.88, max(max(qn.r, qn.g), max(qn.b, qn.a))));
    }

    // Continuous morphological dilation over radius 3 in quad space
    float max_clip = 0.0;
    for (int dy = -3; dy <= 3; ++dy) {
        for (int dx = -3; dx <= 3; ++dx) {
            if (abs(dx) + abs(dy) <= 4) {
                vec2 offset = vec2(float(dx), float(dy)) * u_tex_size.zw;
                vec4 quad = texture(u_base_bayer, tex_coord + offset);
                vec4 q_norm = (quad - u_black_level) * norm;
                float q_max = max(max(q_norm.r, q_norm.g), max(q_norm.b, q_norm.a));
                // Ramp from 0.82 to 0.96 so clipped light sources and filaments are reliably captured
                float c = smoothstep(0.82, 0.96, q_max);
                max_clip = max(max_clip, c);
            }
        }
    }

    o_clip_mask = vec2(max_clip, near_clip);
}
)FM";
