// sh018: quarantine_reduce (+0xec): safety gate sums
static const char* kFastQuarReduce=R"FM(#version 310 es
precision highp float;
precision highp int;

layout(local_size_x = 16, local_size_y = 16) in;

layout(binding = 0) uniform highp sampler2D u_quarantine_tex;
uniform ivec2 u_size;
uniform float u_safety_gate_motion_thresh;
uniform int u_reset_reject;

layout(std430, binding = 0) buffer QuarantineStats {
    float out_sum_invalid;
    float out_sum_clipped;
    float out_sum_mask;
    float out_reserved;
};

layout(std430, binding = 1) readonly buffer HomoResultBuffer {
    float in_h[9];
    uint in_inliers;
    uint in_tracked_count;
    float in_inlier_ratio;
    uint in_valid;
};

shared float s_inv[256];
shared float s_clip[256];
shared float s_mask[256];

void main() {
    uint tid = gl_LocalInvocationIndex;
    float my_inv = 0.0;
    float my_clip = 0.0;
    float my_mask = 0.0;

    for (int y = int(gl_LocalInvocationID.y); y < u_size.y; y += 16) {
        for (int x = int(gl_LocalInvocationID.x); x < u_size.x; x += 16) {
            vec4 pix = texelFetch(u_quarantine_tex, ivec2(x, y), 0);
            my_inv += pix.g;
            my_clip += pix.b;
            my_mask += pix.a;
        }
    }

    s_inv[tid] = my_inv;
    s_clip[tid] = my_clip;
    s_mask[tid] = my_mask;
    barrier();

    for (uint s = 128u; s > 0u; s >>= 1) {
        if (tid < s) {
            s_inv[tid] += s_inv[tid + s];
            s_clip[tid] += s_clip[tid + s];
            s_mask[tid] += s_mask[tid + s];
        }
        barrier();
    }

    if (tid == 0u) {
        out_sum_invalid = s_inv[0];
        out_sum_clipped = s_clip[0];
        out_sum_mask = s_mask[0];
        out_reserved = (in_valid != 0u) ? 1.0 : 0.0;
    }
}
)FM";
