static const char* kFastHlCleanValid=R"FM(#version 310 es
precision highp float;
precision highp int;

in highp vec2 tex_coord;
layout(location = 0) out float o_clean_valid;

uniform sampler2D u_valid_tex;
uniform sampler2D u_quarantine_tex;
uniform int u_use_quarantine;
uniform vec4 u_tex_size; // zw = (1/(W/2), 1/(H/2))

float median9_valid(float a[9]) {
    for (int i = 0; i < 5; i++) {
        int min_idx = i;
        for (int j = i + 1; j < 9; j++) {
            if (a[j] < a[min_idx]) min_idx = j;
        }
        float tmp = a[i]; a[i] = a[min_idx]; a[min_idx] = tmp;
    }
    return a[4];
}

void main() {
    float v[9];
    float sum_v = 0.0;
    float min_v = 1.0;
    int n_bad = 0;
    int idx = 0;

    for (int dy = -1; dy <= 1; ++dy) {
        for (int dx = -1; dx <= 1; ++dx) {
            vec2 off = vec2(float(dx) * u_tex_size.z, float(dy) * u_tex_size.w);
            float val = texture(u_valid_tex, tex_coord + off).r;
            v[idx++] = val;
            sum_v += val;
            min_v = min(min_v, val);
            n_bad += val < 0.35 ? 1 : 0; // clearly invalid (a copy's line 0.05 - 0.3; a light's rim ~0.4 is not one)
        }
    }

    // 1. Median 3x3: completely eliminates isolated black holes and rogue white specks
    float med_v = median9_valid(v);

    // 2. Average in 3x3 window: smooth gradient
    float avg_v = sum_v / 9.0;

    // 3. Continuous soft falloff towards motion:
    float clean_v = min(med_v, avg_v);
    // P497: a thin invalid line (a near wire whose parallax the flow missed, SCA_20261104_073400) is a structure, not a speck: the
    // median would erase it and the short frame's copy of the wire would stay; 3+ invalid of 9 keep it, widened by one pixel
    if (n_bad >= 3) clean_v = min_v;

    // Soft cosine ease near the contact boundary to prevent chroma fringing without hard cuts
    float safety = smoothstep(0.02, 0.40, clean_v);
    float out_v = clean_v * safety;

    if (u_use_quarantine != 0) {
        float q_infected = texture(u_quarantine_tex, tex_coord).r;
        float island_valid = 1.0 - smoothstep(0.05, 0.75, q_infected);
        out_v *= island_valid;
    }

    o_clean_valid = out_v;
}
)FM";
// sh042: highlight_apply_validity (+0x15c)
static const char* kFastHlApplyValidity=R"FM(#version 310 es
precision highp float;
precision highp int;

in highp vec2 tex_coord;
layout(location = 0) out float o_final_mask;

uniform sampler2D u_base_mask;
uniform sampler2D u_valid_accum;
uniform vec4 u_tex_size; // zw = (1/(W/2), 1/(H/2))
uniform float u_scale_factor;

layout(std430, binding = 0) readonly buffer QuarantineStats {
    float in_sum_invalid;
    float in_sum_clipped;
    float in_sum_mask;
    float in_reserved;
};

void main() {
    if (false && in_reserved < 0.5) {
        o_final_mask = 0.0;
        return;
    }
    float base_m = texture(u_base_mask, tex_coord).r;
    float valid = texture(u_valid_accum, tex_coord).r;
    float filter_rad = 1.5;
    vec2 dx = vec2(u_tex_size.z * filter_rad, 0.0);
    vec2 dy = vec2(0.0, u_tex_size.w * filter_rad);

    float center = base_m * valid;
    float sum = center * 0.25;

    // Direct 4-neighbors
    sum += (texture(u_base_mask, tex_coord + dx).r * texture(u_valid_accum, tex_coord + dx).r) * 0.125;
    sum += (texture(u_base_mask, tex_coord - dx).r * texture(u_valid_accum, tex_coord - dx).r) * 0.125;
    sum += (texture(u_base_mask, tex_coord + dy).r * texture(u_valid_accum, tex_coord + dy).r) * 0.125;
    sum += (texture(u_base_mask, tex_coord - dy).r * texture(u_valid_accum, tex_coord - dy).r) * 0.125;

    // Diagonal 4-neighbors
    sum += (texture(u_base_mask, tex_coord + dx + dy).r * texture(u_valid_accum, tex_coord + dx + dy).r) * 0.0625;
    sum += (texture(u_base_mask, tex_coord - dx + dy).r * texture(u_valid_accum, tex_coord - dx + dy).r) * 0.0625;
    sum += (texture(u_base_mask, tex_coord + dx - dy).r * texture(u_valid_accum, tex_coord + dx - dy).r) * 0.0625;
    sum += (texture(u_base_mask, tex_coord - dx - dy).r * texture(u_valid_accum, tex_coord - dx - dy).r) * 0.0625;

    o_final_mask = clamp(sum, 0.0, 1.0);
}
)FM";
